const body = $input.first().json.body || $input.first().json;
const { jiraDomain, jiraEmail, jiraApiToken, projectKey, epics } = body;

if (!jiraDomain || !jiraEmail || !jiraApiToken) {
  throw new Error("Thiếu thông tin kết nối Jira (jiraDomain, jiraEmail, jiraApiToken). Vui lòng kiểm tra lại cấu hình!");
}

if (!projectKey) {
  throw new Error("Thiếu Jira Project Key (ví dụ: KAN, PROJ).");
}

if (!Array.isArray(epics) || epics.length === 0) {
  throw new Error("Danh sách epics rỗng. Vui lòng phân tích yêu cầu trước khi đẩy lên Jira!");
}

const cleanDomain = jiraDomain.replace(/\/+$/, "");
const authHeader = "Basic " + Buffer.from(`${jiraEmail}:${jiraApiToken}`).toString("base64");

async function createJiraIssue(fields) {
  const url = `${cleanDomain}/rest/api/2/issue`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      "Authorization": authHeader,
      "Content-Type": "application/json",
      "Accept": "application/json"
    },
    body: JSON.stringify({ fields })
  });

  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const errorDetails = data.errorMessages?.join(", ") || JSON.stringify(data.errors || data);
    throw new Error(`Jira API Error (${res.status}): ${errorDetails}`);
  }

  return data;
}

const createdIssues = [];
let epicsCount = 0;
let storiesCount = 0;
let tasksCount = 0;

// Vòng lặp cấp 1: Tạo các Epic
for (const epic of epics) {
  const epicTitle = epic.title || "Untitled Epic";
  const epicDesc = epic.description || epicTitle;

  let epicRes;
  try {
    epicRes = await createJiraIssue({
      project: { key: projectKey },
      summary: epicTitle,
      description: epicDesc,
      issuetype: { name: "Epic" }
    });
  } catch (err) {
    throw new Error(`Lỗi khi tạo Epic "${epicTitle}": ${err.message}`);
  }

  const epicKey = epicRes.key;
  epicsCount++;
  createdIssues.push({
    type: "Epic",
    key: epicKey,
    id: epicRes.id,
    title: epicTitle,
    parent: null,
    assignee: null,
    url: `${cleanDomain}/browse/${epicKey}`
  });

  // Vòng lặp cấp 2: Tạo các Story thuộc Epic này (lấy ID/Key Epic)
  const stories = epic.stories || epic.user_stories || [];
  for (const story of stories) {
    const storyTitle = story.title || "Untitled Story";
    const storyDesc = story.description || storyTitle;

    const storyFields = {
      project: { key: projectKey },
      summary: storyTitle,
      description: storyDesc,
      issuetype: { name: "Story" },
      parent: { key: epicKey }
    };
    if (story.assigneeId) {
      storyFields.assignee = { accountId: story.assigneeId };
    }

    let storyRes;
    try {
      storyRes = await createJiraIssue(storyFields);
    } catch (err) {
      throw new Error(`Lỗi khi tạo Story "${storyTitle}" thuộc Epic ${epicKey}: ${err.message}`);
    }

    const storyKey = storyRes.key;
    storiesCount++;
    createdIssues.push({
      type: "Story",
      key: storyKey,
      id: storyRes.id,
      title: storyTitle,
      parent: epicKey,
      assignee: story.assigneeName || null,
      url: `${cleanDomain}/browse/${storyKey}`
    });

    // Vòng lặp cấp 3: Tạo các Sub-task thuộc Story này (lấy ID/Key Story)
    const tasks = story.tasks || story.subtasks || [];
    for (const task of tasks) {
      const taskTitle = typeof task === "string" ? task : task.title || "Untitled Subtask";
      const taskDesc = typeof task === "object" ? task.description || taskTitle : taskTitle;
      const assigneeId = typeof task === "object" ? task.assigneeId : null;
      const assigneeName = typeof task === "object" ? task.assigneeName : null;

      const taskFields = {
        project: { key: projectKey },
        summary: taskTitle,
        description: taskDesc,
        issuetype: { name: "Subtask" },
        parent: { key: storyKey }
      };
      if (assigneeId) {
        taskFields.assignee = { accountId: assigneeId };
      }

      let taskRes;
      try {
        taskRes = await createJiraIssue(taskFields);
      } catch (err) {
        // Thử lại với loại issue "Sub-task" nếu cấu hình Jira sử dụng tên này
        try {
          const taskFieldsRetry = {
            project: { key: projectKey },
            summary: taskTitle,
            description: taskDesc,
            issuetype: { name: "Sub-task" },
            parent: { key: storyKey }
          };
          if (assigneeId) {
            taskFieldsRetry.assignee = { accountId: assigneeId };
          }
          taskRes = await createJiraIssue(taskFieldsRetry);
        } catch (retryErr) {
          throw new Error(`Lỗi khi tạo Subtask "${taskTitle}" thuộc Story ${storyKey}: ${retryErr.message}`);
        }
      }

      const taskKey = taskRes.key;
      tasksCount++;
      createdIssues.push({
        type: "Subtask",
        key: taskKey,
        id: taskRes.id,
        title: taskTitle,
        parent: storyKey,
        assignee: assigneeName || null,
        url: `${cleanDomain}/browse/${taskKey}`
      });
    }
  }
}

return [
  {
    json: {
      success: true,
      message: `Đã tạo thành công ${epicsCount} Epic, ${storiesCount} Story, ${tasksCount} Sub-task trên Jira!`,
      summary: {
        epicsCount,
        storiesCount,
        tasksCount,
        totalIssues: epicsCount + storiesCount + tasksCount
      },
      projectKey,
      jiraDomain: cleanDomain,
      createdIssues
    }
  }
];
